window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d67a8ddc80c6085a"]={"versions": [{"id": "FIG-d67a8ddc80c6085a", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur AUTOSAR Classic Platform. Das Diagramm spezifiziert die zeitliche und funktionale Interaktion zwischen Betriebssystem-Taskumgebung (<code>BSW Task</code>), dem LIN-Interface (<code>LinIf</code>), dem LIN-Treiber (<code>Lin</code>) und dem PDU-Router (<code>PduR</code>) bei der kollisionsfreien Verarbeitung und dem Empfang eines Event-Triggered Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Komponenten:</p>\n<ul class=\"fig-list\"><li><code>BSW Task (OS task or cyclic call)</code>: Kontext zur periodischen Triggerung.\n</li><li><code>«module» PduR</code>: Empfänger der empfangenen PDU im oberen Kommunikationsstack.\n</li><li><code>«module» LinIf</code>: LIN-Interface zur Ablaufsteuerung, PDU-Auflösung und Pufferverwaltung.\n</li><li><code>«module» Lin</code>: LIN-Treiber zur direkten Businteraktion.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>LinIf_MainFunction()</code>: Zyklischer Aufruf des LIN-Interface durch die BSW-Task.\n</li><li><code>RequestFrame()</code>: Interner Aufruf des <code>LinIf</code> zur Frame-Anforderung.\n</li><li><code>Lin_SendFrame(Channel, PduInfoPtr) :Std_ReturnType</code>: Schnittstelle des <code>Lin</code>-Treibers zum Senden des Frame-Headers bzw. Frames auf dem angegebenen Kanal.\n</li><li><code>AllocateRxBuffer()</code>: Interne Pufferallokation innerhalb des <code>Lin</code>-Treibers.\n</li><li><code>Lin_GetStatus(Channel, Lin_SduPtr) : Lin_StatusType</code>: Statusabfrage des Treibers mit Rückgabewert <code>Lin_GetStatus() :LIN_RX_OK</code>.\n</li><li><code>ResolvePid()</code>: Interne Identifikation des empfangenen Response-Identifiers im <code>LinIf</code>.\n</li><li><code>PduR_LinIfRxIndication(RxPduId, PduInfoPtr)</code>: Indikations-Callback an den PDU-Router.\n</li><li><code>CopyBuffer()</code>: Lokales Kopieren der Nutzdaten im <code>PduR</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf erstreckt sich über drei Zyklen der <code>LinIf_MainFunction()</code>:</p>\n<ol class=\"fig-list\"><li>Erster Zyklus: Die BSW-Task ruft <code>LinIf_MainFunction()</code> auf. Das <code>LinIf</code> stößt intern <code>RequestFrame()</code> an und übergibt den Frame per <code>Lin_SendFrame(Channel, PduInfoPtr)</code> synchron an den <code>Lin</code>-Treiber. Der Treiber reserviert intern mittels <code>AllocateRxBuffer()</code> Empfangspuffer und kehrt zurück; anschließend endet der erste Task-Zyklus.\n</li><li>Zweiter Zyklus: Die BSW-Task ruft erneut <code>LinIf_MainFunction()</code> auf, die ohne weitere Bus-Interaktion direkt zurückkehrt (Übertragung/Empfang auf dem Bus läuft noch).\n</li><li>Dritter Zyklus: Die BSW-Task triggert <code>LinIf_MainFunction()</code>. Das <code>LinIf</code> fragt per <code>Lin_GetStatus(Channel, Lin_SduPtr)</code> den Status des LIN-Treibers ab, welcher mit <code>LIN_RX_OK</code> den erfolgreichen Empfang bestätigt. Das <code>LinIf</code> löst daraufhin intern über <code>ResolvePid()</code> anhand der empfangenen PID die zugehörige PDU auf und leitet die Daten über <code>PduR_LinIfRxIndication(RxPduId, PduInfoPtr)</code> an das PDU-Router-Modul weiter. Der <code>PduR</code> führt intern <code>CopyBuffer()</code> aus und quittiert den Aufruf, woraufhin die Ausführung der <code>LinIf_MainFunction()</code> und der BSW-Task abgeschlossen wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Polling- und Indikationsmodell für Event-Triggered Frames ohne Buskollision im LIN-Master-Betrieb:</p>\n<ul class=\"fig-list\"><li>Asynchrones Abfragemodell: Das LIN-Interface puffert Frame-Zustände über mehrere Zyklen der <code>LinIf_MainFunction()</code> hinweg und fragt den Hardware-Status über die standardisierte Treiberfunktion <code>Lin_GetStatus()</code> ab.\n</li><li>PDU-Zuordnung: Bei kollisionsfreier Beantwortung eines Event-Triggered Frames ist das LIN-Interface verpflichtet, die PID über <code>ResolvePid()</code> aufzulösen und die resultierende <code>RxPduId</code> an den oberen Layer (<code>PduR</code>) zu übergeben.\n</li><li>Pufferbehandlung: Der Aufrufer (<code>LinIf</code>) stellt <code>Lin_SduPtr</code> bereit, während der obere Kommunikationspartner (<code>PduR</code>) im Rahmen von <code>PduR_LinIfRxIndication</code> per <code>CopyBuffer()</code> für das Auslesen der Nutzdaten verantwortlich ist.\n</li></ul>"}, {"id": "FIG-f7c288d01161f6df", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur AUTOSAR Classic Platform. Das Diagramm spezifiziert die zeitliche und funktionale Interaktion zwischen Betriebssystem-Taskumgebung (<code>BSW Task</code>), dem LIN-Interface (<code>LinIf</code>), dem LIN-Treiber (<code>Lin</code>) und dem generischen oberen Benutzerlayer (<code>LinIf User</code>) bei der kollisionsfreien Verarbeitung und dem Empfang eines Event-Triggered Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Komponenten:</p>\n<ul class=\"fig-list\"><li><code>BSW Task (OS task or cyclic call)</code>: Kontext zur periodischen Triggerung.\n</li><li><code>«module» LinIf User</code>: Generischer oberer Benutzerlayer des LIN-Interface (z. B. PduR oder LinNm).\n</li><li><code>«module» LinIf</code>: LIN-Interface zur Ablaufsteuerung, PDU-Auflösung und Pufferverwaltung.\n</li><li><code>«module» Lin</code>: LIN-Treiber zur direkten Businteraktion.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>LinIf_MainFunction()</code>: Zyklischer Aufruf des LIN-Interface durch die BSW-Task.\n</li><li><code>RequestFrame()</code>: Interner Aufruf des <code>LinIf</code> zur Frame-Anforderung.\n</li><li><code>Lin_SendFrame(Channel, PduInfoPtr)</code>: Schnittstelle des <code>Lin</code>-Treibers zum Senden des Frame-Headers bzw. Frames auf dem angegebenen Kanal.\n</li><li><code>AllocateRxBuffer()</code>: Interne Pufferallokation innerhalb des <code>Lin</code>-Treibers.\n</li><li><code>Lin_GetStatus(Channel, Lin_SduPtr) : Lin_StatusType</code>: Statusabfrage des Treibers mit Rückgabewert <code>Lin_GetStatus() :LIN_RX_OK</code>.\n</li><li><code>ResolvePid()</code>: Interne Identifikation des empfangenen Response-Identifiers im <code>LinIf</code>.\n</li><li><code>&lt;User_RxIndication&gt;(RxPduId, PduInfoPtr)</code>: Konfigurierbarer Indikations-Callback an den LinIf-Benutzer.\n</li><li><code>CopyBuffer()</code>: Lokales Kopieren der Nutzdaten im oberen Layer (<code>LinIf User</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf erstreckt sich über drei Zyklen der <code>LinIf_MainFunction()</code>:</p>\n<ol class=\"fig-list\"><li>Erster Zyklus: Die BSW-Task ruft <code>LinIf_MainFunction()</code> auf. Das <code>LinIf</code> stößt intern <code>RequestFrame()</code> an und übergibt den Frame per <code>Lin_SendFrame(Channel, PduInfoPtr)</code> synchron an den <code>Lin</code>-Treiber. Der Treiber reserviert intern mittels <code>AllocateRxBuffer()</code> Empfangspuffer und kehrt zurück; anschließend endet der erste Task-Zyklus.\n</li><li>Zweiter Zyklus: Die BSW-Task ruft erneut <code>LinIf_MainFunction()</code> auf, die ohne weitere Bus-Interaktion direkt zurückkehrt (Übertragung/Empfang auf dem Bus läuft noch).\n</li><li>Dritter Zyklus: Die BSW-Task triggert <code>LinIf_MainFunction()</code>. Das <code>LinIf</code> fragt per <code>Lin_GetStatus(Channel, Lin_SduPtr)</code> den Status des LIN-Treibers ab, welcher mit <code>LIN_RX_OK</code> den erfolgreichen Empfang bestätigt. Das <code>LinIf</code> löst daraufhin intern über <code>ResolvePid()</code> anhand der empfangenen PID die zugehörige PDU auf und leitet die Daten über den Callback <code>&lt;User_RxIndication&gt;(RxPduId, PduInfoPtr)</code> an das Modul <code>LinIf User</code> weiter. Dieser führt intern <code>CopyBuffer()</code> aus und quittiert den Aufruf, woraufhin die Ausführung der <code>LinIf_MainFunction()</code> und der BSW-Task abgeschlossen wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Polling- und Indikationsmodell für Event-Triggered Frames ohne Buskollision im LIN-Master-Betrieb:</p>\n<ul class=\"fig-list\"><li>Asynchrones Abfragemodell: Das LIN-Interface puffert Frame-Zustände über mehrere Zyklen der <code>LinIf_MainFunction()</code> hinweg und fragt den Hardware-Status über die standardisierte Treiberfunktion <code>Lin_GetStatus()</code> ab.\n</li><li>Generische Benutzer-Anbindung: Der Empfangspfad ist nicht fest an ein bestimmtes Modul gekoppelt; nach Auflösung der PID (<code>ResolvePid()</code>) wird die konfigurierte Empfangsbenachrichtigung <code>&lt;User_RxIndication&gt;</code> aufgerufen.\n</li><li>Pufferbehandlung: Der Aufrufer (<code>LinIf</code>) stellt <code>Lin_SduPtr</code> bereit, während der obere Kommunikationspartner (<code>LinIf User</code>) im Rahmen von <code>&lt;User_RxIndication&gt;</code> per <code>CopyBuffer()</code> für das Auslesen der Nutzdaten verantwortlich ist.\n</li></ul>"}, {"id": "FIG-b5bc73569a490ac0", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur AUTOSAR Classic Platform. Das Diagramm spezifiziert die zeitliche und funktionale Interaktion zwischen Betriebssystem-Taskumgebung (<code>BSW Task</code>), dem LIN-Interface (<code>LinIf</code>), dem LIN-Treiber (<code>Lin</code>) und dem generischen oberen Benutzerlayer (<code>LinIf User</code>) bei der kollisionsfreien Verarbeitung und dem Empfang eines Event-Triggered Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Komponenten:</p>\n<ul class=\"fig-list\"><li><code>BSW Task (OS task or cyclic call)</code>: Kontext zur periodischen Triggerung.\n</li><li><code>«module» LinIf User</code>: Generischer oberer Benutzerlayer des LIN-Interface (z. B. PduR oder LinNm).\n</li><li><code>«module» LinIf</code>: LIN-Interface zur Ablaufsteuerung, PDU-Auflösung und Pufferverwaltung.\n</li><li><code>«module» Lin</code>: LIN-Treiber zur direkten Businteraktion.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>LinIf_MainFunction()</code>: Zyklischer Aufruf des LIN-Interface durch die BSW-Task.\n</li><li><code>RequestFrame()</code>: Interner Aufruf des <code>LinIf</code> zur Frame-Anforderung.\n</li><li><code>Lin_SendFrame(Channel, PduInfoPtr)</code>: Schnittstelle des <code>Lin</code>-Treibers zum Senden des Frame-Headers bzw. Frames auf dem angegebenen Kanal.\n</li><li><code>AllocateRxBuffer()</code>: Interne Pufferallokation innerhalb des <code>Lin</code>-Treibers.\n</li><li><code>Lin_GetStatus(Channel, Lin_SduPtr) : Lin_StatusType</code>: Statusabfrage des Treibers mit Rückgabewert <code>Lin_GetStatus() :LIN_RX_OK</code>.\n</li><li><code>ResolvePid()</code>: Interne Identifikation des empfangenen Response-Identifiers im <code>LinIf</code>.\n</li><li><code>&lt;User_RxIndication&gt;(RxPduId, PduInfoPtr)</code>: Konfigurierbarer Indikations-Callback an den LinIf-Benutzer.\n</li><li><code>CopyBuffer()</code>: Lokales Kopieren der Nutzdaten im oberen Layer (<code>LinIf User</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf erstreckt sich über drei Zyklen der <code>LinIf_MainFunction()</code>:</p>\n<ol class=\"fig-list\"><li>Erster Zyklus: Die BSW-Task ruft <code>LinIf_MainFunction()</code> auf. Das <code>LinIf</code> stößt intern <code>RequestFrame()</code> an und übergibt den Frame per <code>Lin_SendFrame(Channel, PduInfoPtr)</code> synchron an den <code>Lin</code>-Treiber. Der Treiber reserviert intern mittels <code>AllocateRxBuffer()</code> Empfangspuffer und kehrt zurück; anschließend endet der erste Task-Zyklus.\n</li><li>Zweiter Zyklus: Die BSW-Task ruft erneut <code>LinIf_MainFunction()</code> auf, die ohne weitere Bus-Interaktion direkt zurückkehrt (Übertragung/Empfang auf dem Bus läuft noch).\n</li><li>Dritter Zyklus: Die BSW-Task triggert <code>LinIf_MainFunction()</code>. Das <code>LinIf</code> fragt per <code>Lin_GetStatus(Channel, Lin_SduPtr)</code> den Status des LIN-Treibers ab, welcher mit <code>LIN_RX_OK</code> den erfolgreichen Empfang bestätigt. Das <code>LinIf</code> löst daraufhin intern über <code>ResolvePid()</code> anhand der empfangenen PID die zugehörige PDU auf und leitet die Daten über den Callback <code>&lt;User_RxIndication&gt;(RxPduId, PduInfoPtr)</code> an das Modul <code>LinIf User</code> weiter. Dieser führt intern <code>CopyBuffer()</code> aus und quittiert den Aufruf, woraufhin die Ausführung der <code>LinIf_MainFunction()</code> und der BSW-Task abgeschlossen wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Polling- und Indikationsmodell für Event-Triggered Frames ohne Buskollision im LIN-Master-Betrieb:</p>\n<ul class=\"fig-list\"><li>Asynchrones Abfragemodell: Das LIN-Interface puffert Frame-Zustände über mehrere Zyklen der <code>LinIf_MainFunction()</code> hinweg und fragt den Hardware-Status über die standardisierte Treiberfunktion <code>Lin_GetStatus()</code> ab.\n</li><li>Generische Benutzer-Anbindung: Der Empfangspfad ist nicht fest an ein bestimmtes Modul gekoppelt; nach Auflösung der PID (<code>ResolvePid()</code>) wird die konfigurierte Empfangsbenachrichtigung <code>&lt;User_RxIndication&gt;</code> aufgerufen.\n</li><li>Pufferbehandlung: Der Aufrufer (<code>LinIf</code>) stellt <code>Lin_SduPtr</code> bereit, während der obere Kommunikationspartner (<code>LinIf User</code>) im Rahmen von <code>&lt;User_RxIndication&gt;</code> per <code>CopyBuffer()</code> für das Auslesen der Nutzdaten verantwortlich ist.\n</li></ul>"}, {"id": "FIG-b5a50007b34cd520", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur AUTOSAR Classic Platform. Das Diagramm spezifiziert die zeitliche und funktionale Interaktion zwischen Betriebssystem-Taskumgebung (<code>BSW Task</code>), dem LIN-Interface (<code>LinIf</code>), dem LIN-Treiber (<code>Lin</code>) und dem generischen oberen Benutzerlayer (<code>LinIf User</code>) bei der kollisionsfreien Verarbeitung und dem Empfang eines Event-Triggered Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Komponenten:</p>\n<ul class=\"fig-list\"><li><code>BSW Task (OS task or cyclic call)</code>: Kontext zur periodischen Triggerung.\n</li><li><code>«module» LinIf User</code>: Generischer oberer Benutzerlayer des LIN-Interface (z. B. PduR oder LinNm).\n</li><li><code>«module» LinIf</code>: LIN-Interface zur Ablaufsteuerung, PDU-Auflösung und Pufferverwaltung.\n</li><li><code>«module» Lin</code>: LIN-Treiber zur direkten Businteraktion.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>LinIf_MainFunction_&lt;ChannelId&gt;()</code>: Kanalspezifischer zyklischer Aufruf des LIN-Interface durch die BSW-Task.\n</li><li><code>RequestFrame()</code>: Interner Aufruf des <code>LinIf</code> zur Frame-Anforderung.\n</li><li><code>Lin_SendFrame(Channel, PduInfoPtr)</code>: Schnittstelle des <code>Lin</code>-Treibers zum Senden des Frame-Headers bzw. Frames auf dem angegebenen Kanal.\n</li><li><code>AllocateRxBuffer()</code>: Interne Pufferallokation innerhalb des <code>Lin</code>-Treibers.\n</li><li><code>Lin_GetStatus(Channel, Lin_SduPtr) : Lin_StatusType</code>: Statusabfrage des Treibers mit Rückgabewert <code>Lin_GetStatus() :LIN_RX_OK</code>.\n</li><li><code>ResolvePid()</code>: Interne Identifikation des empfangenen Response-Identifiers im <code>LinIf</code>.\n</li><li><code>&lt;User_RxIndication&gt;(RxPduId, PduInfoPtr)</code>: Konfigurierbarer Indikations-Callback an den LinIf-Benutzer.\n</li><li><code>CopyBuffer()</code>: Lokales Kopieren der Nutzdaten im oberen Layer (<code>LinIf User</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf erstreckt sich über drei Zyklen der kanalspezifischen Hauptfunktion:</p>\n<ol class=\"fig-list\"><li>Erster Zyklus: Die BSW-Task ruft <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code> auf. Das <code>LinIf</code> stößt intern <code>RequestFrame()</code> an und übergibt den Frame per <code>Lin_SendFrame(Channel, PduInfoPtr)</code> synchron an den <code>Lin</code>-Treiber. Der Treiber reserviert intern mittels <code>AllocateRxBuffer()</code> Empfangspuffer und kehrt zurück; anschließend endet der erste Task-Zyklus.\n</li><li>Zweiter Zyklus: Die BSW-Task ruft erneut <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code> auf, die ohne weitere Bus-Interaktion direkt zurückkehrt (Übertragung/Empfang auf dem Bus läuft noch).\n</li><li>Dritter Zyklus: Die BSW-Task triggert <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code>. Das <code>LinIf</code> fragt per <code>Lin_GetStatus(Channel, Lin_SduPtr)</code> den Status des LIN-Treibers ab, welcher mit <code>LIN_RX_OK</code> den erfolgreichen Empfang bestätigt. Das <code>LinIf</code> löst daraufhin intern über <code>ResolvePid()</code> anhand der empfangenen PID die zugehörige PDU auf und leitet die Daten über den Callback <code>&lt;User_RxIndication&gt;(RxPduId, PduInfoPtr)</code> an das Modul <code>LinIf User</code> weiter. Dieser führt intern <code>CopyBuffer()</code> aus und quittiert den Aufruf, woraufhin die Ausführung von <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code> und der BSW-Task abgeschlossen wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Polling- und Indikationsmodell für Event-Triggered Frames ohne Buskollision im LIN-Master-Betrieb:</p>\n<ul class=\"fig-list\"><li>Asynchrones Abfragemodell: Das LIN-Interface puffert Frame-Zustände über mehrere Zyklen der kanalspezifischen <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code> hinweg und fragt den Hardware-Status über die standardisierte Treiberfunktion <code>Lin_GetStatus()</code> ab.\n</li><li>Kanaltrennung: Die zyklische Bearbeitung erfolgt getrennt pro Kanal über <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code>.\n</li><li>Generische Benutzer-Anbindung: Der Empfangspfad ist nicht fest an ein bestimmtes Modul gekoppelt; nach Auflösung der PID (<code>ResolvePid()</code>) wird die konfigurierte Empfangsbenachrichtigung <code>&lt;User_RxIndication&gt;</code> aufgerufen.\n</li><li>Pufferbehandlung: Der Aufrufer (<code>LinIf</code>) stellt <code>Lin_SduPtr</code> bereit, während der obere Kommunikationspartner (<code>LinIf User</code>) im Rahmen von <code>&lt;User_RxIndication&gt;</code> per <code>CopyBuffer()</code> für das Auslesen der Nutzdaten verantwortlich ist.\n</li></ul>"}], "trans": [{"from": "FIG-d67a8ddc80c6085a", "to": "FIG-f7c288d01161f6df", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Modul <code>«module» PduR</code> umbenannt / generalisiert zu <code>«module» LinIf User</code>.\n</li><li>Schnittstellenaufruf <code>PduR_LinIfRxIndication(RxPduId, PduInfoPtr)</code> geändert zu parametrisiertem Callback <code>&lt;User_RxIndication&gt;(RxPduId, PduInfoPtr)</code>.\n</li><li>Rückgabetyp <code>:Std_ReturnType</code> beim synchronen Aufruf <code>Lin_SendFrame(Channel, PduInfoPtr)</code> im Diagramm entfernt.\n</li></ul>"}, {"from": "FIG-f7c288d01161f6df", "to": "FIG-b5bc73569a490ac0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b5bc73569a490ac0", "to": "FIG-b5a50007b34cd520", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Zyklischer Funktionsaufruf von <code>LinIf_MainFunction()</code> auf kanalspezifische Signatur <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code> umgestellt (an allen drei Aufrufzeitpunkten).\n</li></ul>"}]};
